const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define geometries
  const kerala = ee.Geometry.Rectangle([74.0, 8.3, 77.5, 12.5]); // Kerala bounding box
  const sriLanka = ee.Geometry.Rectangle([80.0, 5.9, 81.9, 7.8]); // Sri Lanka bounding box

  // 2. Define time period: July-August 2018
  const startDate = '2018-07-01';
  const endDate = '2018-08-31';

  // 3. Load CHIRPS precipitation dataset
  const chirps = ee.ImageCollection('UCSB-CHG/CHIRPS/PENTAD')
    .filterDate(startDate, endDate);

  const size = chirps.size().getInfo();
  print(`CHIRPS Collection Size: ${size}`);

  if (size === 0) {
    print('No CHIRPS data found for July-August 2018');
    print('C1');
    return;
  }

  // 4. Sum rainfall over the period
  const totalRainfall = chirps.reduce(ee.Reducer.sum());

  // 5. Calculate mean rainfall for Kerala
  const keralaStats = totalRainfall.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: kerala,
    scale: 5000,
    maxPixels: 1e9
  });

  const keralaRainfall = keralaStats.get('precipitation').getInfo();
  const keralaCount = totalRainfall.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: kerala,
    scale: 5000,
    maxPixels: 1e9
  }).get('precipitation').getInfo();

  // 6. Calculate mean rainfall for Sri Lanka
  const sriLankaStats = totalRainfall.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: sriLanka,
    scale: 5000,
    maxPixels: 1e9
  });

  const sriLankaRainfall = sriLankaStats.get('precipitation').getInfo();
  const sriLankaCount = totalRainfall.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: sriLanka,
    scale: 5000,
    maxPixels: 1e9
  }).get('precipitation').getInfo();

  // 7. Validation checks
  print(`Kerala - Mean Rainfall: ${keralaRainfall?.toFixed(2)} mm, Pixels: ${keralaCount}`);
  print(`Sri Lanka - Mean Rainfall: ${sriLankaRainfall?.toFixed(2)} mm, Pixels: ${sriLankaCount}`);

  // Check for valid data
  if (keralaCount === 0 || sriLankaCount === 0) {
    print('No valid pixels after processing');
    print('C2');
    return;
  }

  if (keralaRainfall === null || sriLankaRainfall === null || 
      isNaN(keralaRainfall) || isNaN(sriLankaRainfall) ||
      keralaRainfall < 0 || sriLankaRainfall < 0) {
    print('Invalid rainfall values detected');
    print('C3');
    return;
  }

  // 8. Compare rainfall
  print(`Difference: ${(keralaRainfall - sriLankaRainfall).toFixed(2)} mm`);

  if (keralaRainfall > sriLankaRainfall) {
    print('A');
  } else {
    print('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
